void UDAoCBridgeSubsystem::EnsureChatLayout(){if(bChatLayoutReady)return;bChatLayoutReady=true;bChatCombatOpen=true;ChatSizes[0]=FVector2D(400,112);ChatSizes[1]=FVector2D(400,88);ChatTypes[0]={TEXT("say"),TEXT("send"),TEXT("group"),TEXT("guild"),TEXT("officer"),TEXT("alliance"),TEXT("broadcast"),TEXT("emote"),TEXT("advice"),TEXT("chatgroup"),TEXT("help"),TEXT("npc")};ChatTypes[1]={TEXT("system"),TEXT("combat"),TEXT("combat_others"),TEXT("damage_taken"),TEXT("spells"),TEXT("resists"),TEXT("loot"),TEXT("merchant"),TEXT("error")};FVector2D Size(1280,720);if(GetWorld()&&GetWorld()->GetGameViewport())Size=UIViewportSize();if(Size.X<1||Size.Y<1)Size=FVector2D(1280,720);Size/=ClassicScale();ChatPositions[0]=FVector2D(Size.X-ChatSizes[0].X-20./ClassicScale(),Size.Y-ChatSizes[0].Y-22./ClassicScale());ChatPositions[1]=ChatPositions[0]-FVector2D(0,ChatSizes[1].Y+8);}
float UDAoCBridgeSubsystem::ChatReservedHeight()const{return float((ChatSizes[0].Y+(bChatCombatOpen?ChatSizes[1].Y+8:0))*ClassicScale()+22);}
bool UDAoCBridgeSubsystem::ChatHovered()const{for(const auto& Panel:ChatPanels)if(Panel.IsValid()&&Panel->IsHovered())return true;return false;}
void UDAoCBridgeSubsystem::SetChatChannel(int32 Pane,const FString& Kind,bool Enabled){if(Pane<0||Pane>1||!ChatKnown(Kind))return;if(Enabled)ChatTypes[Pane].AddUnique(Kind);else ChatTypes[Pane].Remove(Kind);RefreshChatHistory();SaveClassicLayout();}
void UDAoCBridgeSubsystem::ToggleCombatChat(){bChatCombatOpen=!bChatCombatOpen;if(ChatPanels[1].IsValid())ChatPanels[1]->SetVisibility(bChatCombatOpen?EVisibility::Visible:EVisibility::Collapsed);SaveClassicLayout();}
TSharedRef<SWidget> UDAoCBridgeSubsystem::BuildChatFilterMenu(int32 Pane){FMenuBuilder Menu(true,nullptr);for(int32 I=0;I<UE_ARRAY_COUNT(ChatKinds);++I){FString Kind=ChatKinds[I];Menu.AddMenuEntry(FText::FromString(ChatLabels[I]),FText(),FSlateIcon(),FUIAction(FExecuteAction::CreateLambda([this,Pane,Kind](){SetChatChannel(Pane,Kind,!ChatTypes[Pane].Contains(Kind));}),FCanExecuteAction(),FIsActionChecked::CreateLambda([this,Pane,Kind](){return ChatTypes[Pane].Contains(Kind);})),NAME_None,EUserInterfaceActionType::ToggleButton);}return Menu.MakeWidget();}
