void UDAoCBridgeSubsystem::ApplyChat(TSharedPtr<FJsonObject> Snapshot){
 if(!GetWorld()||!GetWorld()->GetGameViewport())return;ApplyWorldMessages(Snapshot);EnsureChatLayout();if(!ChatOverlay.IsValid()){auto Root=SNew(SCanvas);for(int32 Pane=0;Pane<2;++Pane){Root->AddSlot().Position_Lambda([this,Pane](){FVector2D Size;Size=UIViewportSize();Size/=ClassicScale();return FVector2D(FMath::Clamp(ChatPositions[Pane].X,0.,FMath::Max(0.,Size.X-ChatSizes[Pane].X)),FMath::Clamp(ChatPositions[Pane].Y,0.,FMath::Max(0.,Size.Y-ChatSizes[Pane].Y)));}).Size_Lambda([this,Pane](){return ChatSizes[Pane];})[BuildChatPane(Pane)];}ChatPanels[1]->SetVisibility(bChatCombatOpen?EVisibility::Visible:EVisibility::Collapsed);ChatOverlay=SNew(SDPIScaler).DPIScale_Lambda([this](){return ClassicScale();})[Root];GetWorld()->GetGameViewport()->AddViewportWidgetContent(ChatOverlay.ToSharedRef(),40);}
 const TSharedPtr<FJsonObject>* Typed=nullptr;const TArray<TSharedPtr<FJsonValue>>* Entries=nullptr;if(Snapshot->TryGetObjectField(TEXT("chat"),Typed)&&(*Typed)->TryGetArrayField(TEXT("entries"),Entries)){double Revision=0;(*Typed)->TryGetNumberField(TEXT("revision"),Revision);if(bChatStructured&&ChatRevision==int64(Revision))return;bChatStructured=true;ChatRevision=int64(Revision);ChatState=*Typed;}
 else {FString Signature;const TArray<TSharedPtr<FJsonValue>>* Lines=nullptr;TArray<TSharedPtr<FJsonValue>> Rows;if(Snapshot->TryGetArrayField(TEXT("messages"),Lines)){for(const auto& V:*Lines)if(V->Type==EJson::String){FString Line=V->AsString();Signature+=Line+TEXT("\n");auto E=MakeShared<FJsonObject>();E->SetStringField(TEXT("text"),Line);E->SetStringField(TEXT("kind"),TEXT("system"));Rows.Add(MakeShared<FJsonValueObject>(E));}}if(!bChatStructured&&ChatState.IsValid()&&Signature==ChatLegacySignature)return;ChatLegacySignature=Signature;bChatStructured=false;ChatState=MakeShared<FJsonObject>();ChatState->SetArrayField(TEXT("entries"),Rows);}
 RefreshChatHistory();
}
void UDAoCBridgeSubsystem::RefreshChatHistory(){if(!ChatState.IsValid())return;const TArray<TSharedPtr<FJsonValue>>* Entries=nullptr;if(!ChatState->TryGetArrayField(TEXT("entries"),Entries))return;FString Rendered[2];int32 Start=FMath::Max(0,Entries->Num()-200);for(int32 I=Start;I<Entries->Num();++I){if((*Entries)[I]->Type!=EJson::Object)continue;auto E=(*Entries)[I]->AsObject();FString Kind=ChatStr(E,TEXT("kind"));if(!ChatKnown(Kind))Kind=TEXT("system");FString Text=ChatStr(E,TEXT("text")).Left(4096);for(int32 Pane=0;Pane<2;++Pane)if(ChatTypes[Pane].Contains(Kind)){if(!Rendered[Pane].IsEmpty())Rendered[Pane]+=TEXT("\n");Rendered[Pane]+=TEXT("<")+Kind+TEXT(">")+ChatLiteral(Text)+TEXT("</>");}}
 for(int32 Pane=0;Pane<2;++Pane){auto History=Pane==0?ChatMainHistory:ChatHistory;if(!History.IsValid()||!ChatScroll[Pane].IsValid()||Rendered[Pane]==ChatRendered[Pane])continue;float Offset=ChatScroll[Pane]->GetScrollOffset();ChatRendered[Pane]=Rendered[Pane];History->SetText(FText::FromString(Rendered[Pane]));if(ChatFollow[Pane])ChatScroll[Pane]->ScrollToEnd();else ChatScroll[Pane]->SetScrollOffset(Offset);}}
void UDAoCBridgeSubsystem::ScrollChat(int32 Pane,int32 Pages){if(Pane<0||Pane>1||!ChatScroll[Pane].IsValid())return;float End=ChatScroll[Pane]->GetScrollOffsetOfEnd();float Offset=FMath::Clamp(ChatScroll[Pane]->GetScrollOffset()+float(Pages)*float(FMath::Max(30.,ChatSizes[Pane].Y-35))*.9f,0.f,End);ChatFollow[Pane]=Offset>=End-2;ChatScroll[Pane]->SetScrollOffset(Offset);}
void UDAoCBridgeSubsystem::UpdateChatInput(){for(int32 I=0;I<2;++I)if(ChatFollow[I]&&ChatScroll[I].IsValid()&&ChatScroll[I]->GetScrollOffsetOfEnd()-ChatScroll[I]->GetScrollOffset()>2)ChatScroll[I]->ScrollToEnd();auto* PC=GetWorld()?GetWorld()->GetFirstPlayerController():nullptr;if(!PC||bChatOpen)return;int32 Pane=(PC->IsInputKeyDown(EKeys::LeftShift)||PC->IsInputKeyDown(EKeys::RightShift))?0:1;if(PC->WasInputKeyJustPressed(EKeys::PageUp))ScrollChat(Pane,-1);if(PC->WasInputKeyJustPressed(EKeys::PageDown))ScrollChat(Pane,1);}
void UDAoCBridgeSubsystem::OpenChat(){if(bExiting||Session.IsEmpty()||!bLocalAvailable)return;if(!ChatInput.IsValid())ApplyChat(MakeShared<FJsonObject>());if(!ChatInput.IsValid())return;bChatOpen=true;bMouseLookToggle=false;SetMouseLook(false);ChatInput->SetVisibility(EVisibility::Visible);if(auto* PC=GetWorld()->GetFirstPlayerController()){FInputModeUIOnly Mode;Mode.SetWidgetToFocus(ChatInput);PC->SetInputMode(Mode);PC->bShowMouseCursor=true;}FSlateApplication::Get().SetKeyboardFocus(ChatInput,EFocusCause::SetDirectly);}
void UDAoCBridgeSubsystem::CloseChat(){bChatOpen=false;ChatClosedAt=FPlatformTime::Seconds();if(ChatInput.IsValid()){ChatInput->SetText(FText::GetEmpty());ChatInput->SetVisibility(EVisibility::Collapsed);}if(auto* PC=GetWorld()->GetFirstPlayerController()){FInputModeGameAndUI Mode;Mode.SetHideCursorDuringCapture(false);Mode.SetLockMouseToViewportBehavior(EMouseLockMode::DoNotLock);PC->SetInputMode(Mode);PC->bShowMouseCursor=true;}FSlateApplication::Get().SetAllUserFocusToGameViewport(EFocusCause::SetDirectly);}
void UDAoCBridgeSubsystem::SubmitChat(const FString& Text){const FString Value=Text.TrimStartAndEnd();if(Value.Len()>240||Value.Contains(TEXT("\n"))||Value.Contains(TEXT("\r")))return;if(!Value.IsEmpty()&&!Session.IsEmpty()&&bLocalAvailable&&!bExiting){auto V=MakeShared<FJsonObject>();V->SetStringField(TEXT("text"),Value);Send(TEXT("chat"),V);}CloseChat();}
void UDAoCBridgeSubsystem::RemoveChat(){RemoveWorldMessages();if(bChatOpen)CloseChat();if(ChatOverlay.IsValid()&&GetWorld()&&GetWorld()->GetGameViewport())GetWorld()->GetGameViewport()->RemoveViewportWidgetContent(ChatOverlay.ToSharedRef());ChatOverlay.Reset();ChatInput.Reset();ChatHistory.Reset();ChatMainHistory.Reset();for(int32 I=0;I<2;++I){ChatPanels[I].Reset();ChatScroll[I].Reset();ChatFrames[I].Reset();ChatRendered[I].Empty();ChatFollow[I]=true;}ChatState.Reset();ChatRevision=-1;ChatLegacySignature.Empty();bChatStructured=false;bChatLayoutReady=false;bChatOpen=false;}
